import{_ as r,h as i,i as e,c as s,v as l,p as n,x as o,m as h,e as p,S as d}from"./chunks/framework.Dvtg8yj2.js";const M=JSON.parse('{"title":"MCTS 用于语言模型","description":"","frontmatter":{"title":"MCTS 用于语言模型","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mcts-llm.md","filePath":"llm/mcts-llm.md","lastUpdated":1788454257000}'),m={name:"llm/mcts-llm.md"};function A(E,a,c,B,S,T){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="mcts-用于语言模型" tabindex="-1">MCTS 用于语言模型 <a class="header-anchor" href="#mcts-用于语言模型" aria-label="Permalink to &quot;MCTS 用于语言模型&quot;">​</a></h1><div class="epigraph"><p>用蒙特卡洛树搜索把策略先验与搜索结合起来：选择、扩展、模拟、回传，用访问次数而不是单次贪心来决定走哪一步。</p><footer>—— 对照 Silver 等 AlphaZero（2017）的搜索循环，以及把它套到冻结语言模型上的公开做法</footer></div><p>蒙特卡洛树搜索（MCTS）在 AlphaGo / AlphaZero 里与可学习的策略、价值网络绑在一起，从自我对弈中改进网络。语言模型上的 MCTS 通常 <em>不</em> 重新训练一棵从零开始的棋力：策略先验来自已经训好的 \\(\\pi\\)，逐步或终局打分来自规则、结果模型或<a href="/llm/prm-guided-search">过程奖励</a>，树只存在于一次题目的推理过程中。本篇写清 AlphaZero 对照下，哪些部件被换成了 LLM，哪些没有被换成——尤其不要把一次带搜索的解码写成「语言模型版 AlphaZero 已经完成自我对弈训练」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐步生成是一棵巨大的树：每步分支约等于词表大小。束搜索固定宽度且不回头；独立<a href="/llm/best-of-n">Best-of-N</a> 不共享中间计算，错的前缀会在 \\(N\\) 条里重复付费。需要一种允许 <em>在高价值前缀上加模拟、在低价值前缀上少访问</em> 的预算分配。MCTS 用 UCB 一类指数把探索与利用写进选择规则，使同一笔测试时 FLOPs 不必均匀洒在 \\(N\\) 条完整链上。</p><p>障碍同样具体。棋类动作集小、规则确定、终局可判定；语言动作集是词表，多数 token 不是「一步推理」，模拟（rollout）本身还要再跑模型直到 EOS，代价远高于走子。价值估计若只用终端对错，树深时方差极大；若用 PRM，则搜索质量封顶在过程模型的校准上。公开工作如 Hao 等人 2023 年的 RAP（把语言模型当世界模型做推理规划）、Yao 等人的 Tree of Thoughts，都是在 <em>缩小动作空间</em>（句子级/步骤级分支，而不是每个 token）之后，搜索才跑得动。</p><h3 id="动作粒度必须先切粗" tabindex="-1">动作粒度必须先切粗 <a class="header-anchor" href="#动作粒度必须先切粗" aria-label="Permalink to &quot;动作粒度必须先切粗&quot;">​</a></h3><p>token 级 MCTS 对 32K 词表几乎不可用：扩展一步就要对大量子节点做先验或采样。实践把「动作」定义成一个推理步骤、一行方程、或一个思维句，由模型一次解码出整个动作，再作为树边。这已经不是 AlphaZero 的合法棋步集合，而是用 \\(\\pi\\) 当提议分布的分层搜索。评测应写明分支是步骤还是 token，否则模拟次数不可比。</p><p><span class="marginnote">AlphaZero 的价值网络与策略网络在搜索与自我对弈中 <em>共同训练</em>。LLM+MCTS 的默认形态是网络冻结、只在测试时搜。Snell 等 2024 把带 PRM 的 lookahead 视为去掉随机探索之后的 MCTS 特例，强调测试时更想利用而不是为了学 \\(V\\) 去探索。两套目标不要混写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一次查询上的经典四步：</p><ol><li><strong>选择</strong>：从根沿树走到叶，每步取 \\(\\arg\\max_a Q(s,a)+U(s,a)\\)。\\(U\\) 含先验 \\(P(a\\mid s)\\)（来自 \\(\\pi\\) 的步骤对数概率或采样频率）与访问次数 \\(N\\)。</li><li><strong>扩展</strong>：在叶上向 \\(\\pi\\) 要 \\(k\\) 个新步骤（采样，不是整词表展开）。</li><li><strong>模拟</strong>：从新节点继续生成到可打分的终点，或用 PRM/价值头直接估，免去完整 rollout。</li><li><strong>回传</strong>：把终局或逐步分数加回路径上的 \\(Q\\)。</li></ol><p>预算用模拟次数或生成 token 数衡量。最终答案可以取根上访问最多的子节点，或所有完成轨迹里 \\(s\\) 最高的一条。后者更像在树的叶子上做 BoN。</p>',13)),(e(),n(d,null,{default:o(()=>[p(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%EF%BC%9A%E9%A2%98%E7%9B%AE%22%5D%20--%3E%20SEL%5B%22%E9%80%89%E6%8B%A9%EF%BC%9AQ%20%2B%20%E6%8E%A2%E7%B4%A2%E9%A1%B9%22%5D%0A%20%20SEL%20--%3E%20EXP%5B%22%E6%89%A9%E5%B1%95%EF%BC%9A%CF%80%20%E6%8F%90%E5%87%BA%20k%20%E4%B8%AA%E6%AD%A5%E9%AA%A4%22%5D%0A%20%20EXP%20--%3E%20SIM%5B%22%E6%A8%A1%E6%8B%9F%EF%BC%9A%E7%BB%AD%E5%86%99%E5%88%B0%E7%BB%88%E7%82%B9%E6%88%96%20PRM%20%E4%BC%B0%E5%80%BC%22%5D%0A%20%20SIM%20--%3E%20BACK%5B%22%E5%9B%9E%E4%BC%A0%E6%9B%B4%E6%96%B0%20Q%E3%80%81N%22%5D%0A%20%20BACK%20--%3E%20SEL%0A%20%20BACK%20--%3E%20OUT%5B%22%E5%81%9C%E6%AD%A2%EF%BC%9A%E6%8C%89%E8%AE%BF%E9%97%AE%E6%88%96%E6%8C%89%20s%20%E5%8F%96%E7%AD%94%E6%A1%88%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="与-alphazero-的部件对照" tabindex="-1">与 AlphaZero 的部件对照 <a class="header-anchor" href="#与-alphazero-的部件对照" aria-label="Permalink to &quot;与 AlphaZero 的部件对照&quot;">​</a></h3><p>| 部件 | AlphaZero | 典型 LLM 用法 | | 根状态 | 棋盘 | 提示 + 已写步骤 | | 先验 \\(P\\) | 训练中的策略网 | 冻结 LM 的步骤分布 | | 价值 \\(V\\) | 训练中的价值网 | 规则 / ORM / PRM / 再 decode | | 环境转移 | 确定的规则 | 文本拼接；没有外部棋规 | | 学习 | 自我对弈更新网 | 通常不更新；至多离线存轨迹再 SFT/RL |</p><p>转移函数是「把步骤文本接上去」，世界模型就是语言模型自己——RAP 把这一点写进方法名。没有独立的合法步检查时，树会扩展出语法正确但数学非法的边，只能靠 \\(s\\) 事后打折扣。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>UCB 把预算压向 \\(Q\\) 高且访问少的边。若 \\(Q\\) 来自可靠的逐步分，搜索会在分叉点加模拟，类似人在草稿纸上对可疑步骤多试几次。若 \\(Q\\) 来自嘈杂的终端 0/1，早期深度的节点共享太少终局样本，\\(U\\) 项会把预算浪费在尚未区分的噪声分支上。这就是为什么 PRM 或短 lookahead 往往比纯终局 MCTS 更划算：不是 MCTS 魔法，是方差。</p><p>计算上，每次扩展/模拟都是一次或多次 decode，KV 可以按节点缓存前缀，但节点一多，缓存寿命与显存策略立刻变成系统问题，见<a href="/llm/decode-memory-wall">Decode 的显存墙</a>。共享前缀的树比独立 BoN 更省 prefill，这是 MCTS 在相同 token 预算下有时更优的系统原因，而不只是算法原因。</p><p><span class="marginnote">探索常数 \\(c\\) 与先验温度决定树是瘦而深还是宽而浅。把 \\(c\\) 抄自棋类默认值通常过大：语言模型先验已经很锋利，\\(c\\) 大会变成随机宽度搜索，退化为更贵的采样。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="测试时搜索不是自我对弈训练" tabindex="-1">测试时搜索不是自我对弈训练 <a class="header-anchor" href="#测试时搜索不是自我对弈训练" aria-label="Permalink to &quot;测试时搜索不是自我对弈训练&quot;">​</a></h3><p>不要把「用了 MCTS」写成模型通过搜索学会了推理。冻结 \\(\\pi\\) 上的搜索只改变该次查询的计算图，下次查询树清空。要把搜索轨迹蒸馏回权重，需要额外的 SFT 或 RL 工序，那是训练，应单独报成本。OpenAI 关于 o1 的公开说明强调强化学习与思维链，没有给出可引用的 MCTS 超参；对照应停在博客表述，不要补一篇不存在的树搜索论文。</p><p>步骤切分失败时（模型不分步、一步里塞完整答案），树退化成 BoN。PRM 与 \\(\\pi\\) 来自不同训练分布时，\\(Q\\) 会系统性偏爱某种书写风格。安全：搜索会最大化 \\(s\\)，若 \\(s\\) 不包含拒答，MCTS 比单次采样更会找到越狱完成路径。预算封顶必须同时限制深度、分支和总 token，否则一次难题可以打满服务队列。</p><p><span class="marginnote">可引用：Silver et al., AlphaZero, 2017；Hao et al., <em>Reasoning with Language Model is Planning with World Model</em> (RAP), 2023；Yao et al., Tree of Thoughts, 2023；Snell et al., 2024 中与 lookahead / MCTS 的讨论。不要虚构「LLM-AlphaZero 2024」的 arXiv 编号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LLM 上的 MCTS 多半是冻结策略 + 外部 \\(s\\) 的测试时搜索，不是 AlphaZero 式的自我对弈训练循环。</li><li>动作应切成步骤级，否则词表分支使扩展不可行。</li><li>四步循环仍在；价值来源决定方差，PRM/lookahead 往往比纯终局模拟更划算。</li><li>共享前缀让树搜索在系统上可能优于独立 BoN，但 KV 与节点数会重新碰到显存墙。</li><li>探索常数不能直接抄棋类；\\(c\\) 过大即昂贵随机采样。</li><li>搜索轨迹要进权重必须另做蒸馏或 RL；o1 的内部搜索未公开到可复现的树超参。</li><li>出处：Silver et al., <em>Mastering Chess and Shogi by Self-Play…</em>, 2017；Hao et al., RAP, 2023；Yao et al., <em>Tree of Thoughts</em>, 2023；Snell et al., 2024。</li></ul>',14))])}const u=r(m,[["render",A]]);export{M as __pageData,u as default};
